def solve(*args, **kwargs):
    """Run-length encoding (batch 2).
    Handles being called with no arguments, with a positional string, or with keyword 's'.
    Non-string inputs are treated as empty and return [] as per spec.
    """
    # Determine the string input
    if args:
        s = args[0]
    elif 's' in kwargs:
        s = kwargs['s']
    else:
        # No input provided
        return []
    if not isinstance(s, str):
        return []
    if not s:
        return []
    res = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = ch
            count = 1
    res.append([prev, count])
    return res

