def solve(nums):
    n = len(nums)
    if n < 2:
        return list(nums)
    # Find pivot: rightmost i with nums[i] < nums[i+1].
    i = n - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1
    if i < 0:
        # Last permutation: return sorted (smallest) permutation.
        return sorted(nums)
    # Find rightmost element greater than pivot, swap, then reverse suffix.
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    result = list(nums)
    result[i], result[j] = result[j], result[i]
    result[i + 1:] = reversed(result[i + 1:])
    return result

