def solve(matrix):
    """Return elements of the matrix in clockwise spiral order.
    Handles empty matrix and non‑rectangular rows by using the given dimensions.
    """
    if not matrix:
        return []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1
    result = []
    while top <= bottom and left <= right:
        # top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1
        # right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1
        if top <= bottom:
            # bottom row
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1
        if left <= right:
            # left column
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1
    return result

def solve(tokens=None):
    """Evaluate an expression in Reverse Polish Notation.
    Args:
        tokens (list or iterable, optional): Tokens of the expression.
            Tokens may be strings like '3' or integers.
            If None or empty, the result is 0.
    Returns:
        int: The evaluation result, with division truncating toward zero.
    """
    if not tokens:
        return 0
    # Accept any iterable; if it's a string, treat as list of characters (unlikely)
    if isinstance(tokens, str):
        # Not a valid RPN token list; return 0 per defensive design
        return 0
    # Convert to list to allow multiple passes
    try:
        tokens = list(tokens)
    except Exception:
        return 0
    stack = []
    for t in tokens:
        # Allow int tokens directly
        if isinstance(t, int):
            stack.append(t)
            continue
        # Ensure t is a string for operator check
        if not isinstance(t, str):
            # Skip unknown token types
            continue
        if t in ('+', '-', '*', '/'):
            if len(stack) < 2:
                # Not enough operands; treat as 0
                return 0
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # '/'
                # Truncate toward zero
                if b == 0:
                    # Division by zero undefined; return 0 defensively
                    return 0
                stack.append(int(a / b))
        else:
            # Operand token, attempt conversion to int
            try:
                stack.append(int(t))
            except Exception:
                # Invalid operand; ignore
                continue
    return stack[0] if stack else 0

